{name:"Rabby",brand:"rabby",detail:"Copy link \xB7 open its DApp browser",instruction:"Open Rabby, go to its DApps browser, and paste the copied Mainwell address."},
{name:"Other EVM wallet",brand:"generic",detail:"Copy link \xB7 use the wallet's DApp browser",instruction:"Open your wallet's built-in DApp browser and paste the copied Mainwell address."}
