async function api(path,options={}){const r=await fetch(path,{credentials:"same-origin",...options,headers:{"content-type":"application/json",...(options.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||"Request failed ("+r.status+")");return d}
function short(a){return a.slice(0,8)+"\u2026"+a.slice(-6)}
function setStatus(id,msg,error=false){$(id).textContent=msg;$(id).className="status"+(error?" error":"")}
function isMobileBrowser(){return /Android|iPhone|iPad|iPod/i.test(navigator.userAgent)||((navigator.platform==="MacIntel")&&navigator.maxTouchPoints>1)}
function addDiscoveredProvider(detail){const info=detail?.info,p=detail?.provider;if(!p||typeof p.request!=="function")return;const uuid=typeof info?.uuid==="string"?info.uuid:"";if(uuid&&discoveredProviders.has(uuid))return;if([...discoveredProviders.values()].some(x=>x.provider===p))return;const key=uuid||("legacy-"+discoveredProviders.size);discoveredProviders.set(key,{info:{name:typeof info?.name==="string"?info.name:"EVM wallet",rdns:typeof info?.rdns==="string"?info.rdns:""},provider:p});if(!$("walletModal").classList.contains("hidden"))renderWalletOptions()}
window.addEventListener("eip6963:announceProvider",event=>addDiscoveredProvider(event.detail));
function discoverLegacyProviders(){const eth=window.ethereum;if(!eth)return;const list=Array.isArray(eth.providers)?eth.providers:[eth];for(const p of list){if(!p||typeof p.request!=="function")continue;let name="Browser wallet";if(p.isMetaMask)name="MetaMask";else if(p.isTrust||p.isTrustWallet)name="Trust Wallet";else if(p.isCoinbaseWallet)name="Coinbase Wallet";else if(p.isRabby)name="Rabby";else if(p.isBraveWallet)name="Brave Wallet";else if(p.isRainbow)name="Rainbow";addDiscoveredProvider({info:{name,rdns:""},provider:p})}}
