function walletBrand(name,rdns=""){const value=(name+" "+rdns).toLowerCase();if(value.includes("metamask"))return "metamask";if(value.includes("trust"))return "trustwallet";if(value.includes("coinbase"))return "coinbase";if(value.includes("base"))return "base";if(value.includes("rainbow"))return "rainbow";if(value.includes("rabby"))return "rabby";if(value.includes("brave"))return "brave";return "generic"}
function addWalletButton(root,name,detail,brand,onClick){const button=document.createElement("button");button.type="button";button.className="wallet-choice";button.setAttribute("aria-label",name+" \u2014 "+detail);const mark=document.createElement("span");mark.className="wallet-mark";mark.setAttribute("aria-hidden","true");mark.innerHTML=WALLET_LOGOS[brand]||WALLET_LOGOS.generic;const text=document.createElement("span");const strong=document.createElement("strong");strong.textContent=name;const small=document.createElement("small");small.textContent=detail;text.append(strong,small);button.append(mark,text);button.addEventListener("click",onClick);root.append(button)}
function addSectionLabel(root,label){const e=document.createElement("div");e.className="wallet-section-label";e.textContent=label;root.append(e)}
function renderWalletOptions(){const root=$("walletOptions");root.replaceChildren();const mobile=isMobileBrowser();const found=[...discoveredProviders.values()];if(found.length){addSectionLabel(root,"WALLETS DETECTED IN THIS BROWSER");for(const item of found)addWalletButton(root,item.info.name,"Connect in this browser",walletBrand(item.info.name,item.info.rdns),()=>connectWithProvider(item.provider,item.info.name))}
if(mobile){addSectionLabel(root,found.length?"OPEN MAINWELL IN ANOTHER WALLET":"CONNECT USING YOUR WALLET APP");for(const w of MOBILE_WALLETS)addWalletButton(root,w.name,w.detail,w.brand,async()=>{if(w.url){setStatus("walletModalStatus","Opening "+w.name+"\u2026");location.href=w.url();return}try{await navigator.clipboard.writeText(location.href);setStatus("walletModalStatus","Mainwell link copied. "+w.instruction)}catch{setStatus("walletModalStatus","Copy is unavailable in this browser. Copy the page address, then "+w.instruction,true)}});const note=found.length?"You can also open Mainwell inside another EVM wallet's built-in browser.":"MetaMask and Trust Wallet open Mainwell directly in their wallet apps. Other listed wallets can connect from their built-in DApp browsers."; $("walletModalNote").textContent=note}else if(!found.length){addSectionLabel(root,"GET A WALLET");const links=[{name:"MetaMask",url:"https://metamask.io/download/",brand:"metamask"},{name:"Trust Wallet",url:"https://trustwallet.com/browser-extension",brand:"trustwallet"},{name:"Coinbase Wallet",url:"https://www.coinbase.com/wallet",brand:"coinbase"},{name:"Rabby Wallet",url:"https://rabby.io/",brand:"rabby"},{name:"Rainbow",url:"https://rainbow.me/",brand:"rainbow"}];for(const w of links)addWalletButton(root,w.name,"Visit official wallet site",w.brand,()=>window.open(w.url,"_blank","noopener,noreferrer"));$("walletModalNote").textContent="Install a wallet, refresh Mainwell, then select it here. Brave Wallet is also supported in the Brave browser."}else{$("walletModalNote").textContent="Choose your wallet. Mainwell requests account access and a one-time sign-in signature only."}
}
function openWalletModal(){discoverLegacyProviders();$("walletModal").classList.remove("hidden");setStatus("walletModalStatus","Looking for compatible wallet extensions\u2026");renderWalletOptions();window.dispatchEvent(new Event("eip6963:requestProvider"));setTimeout(()=>{discoverLegacyProviders();renderWalletOptions();setStatus("walletModalStatus","Choose a wallet to continue.")},350)}
