async function provider(){if(activeProvider)return activeProvider;discoverLegacyProviders();const first=discoveredProviders.values().next().value;if(first?.provider)return first.provider;throw new Error("No wallet is connected. Choose a wallet from the connection window.")}
async function connectWithProvider(p,name){const button=$("connect");button.disabled=true;closeWalletModal();activeProvider=p;const chosen=[...discoveredProviders.values()].find(x=>x.provider===p);if(chosen?.info?.rdns)sessionStorage.setItem("mainwell.selectedWalletRdns",chosen.info.rdns);if(chosen?.info?.name)sessionStorage.setItem("mainwell.selectedWalletName",chosen.info.name);attachProviderEvents(p);setStatus("connectStatus","Waiting for "+name+"\u2026");try{const accounts=await p.request({method:"eth_requestAccounts"});account=accounts?.[0]||"";if(!/^0x[0-9a-fA-F]{40}$/.test(account))throw new Error("Wallet did not return a valid account.");chainId=Number(BigInt(await p.request({method:"eth_chainId"})));if(!NETWORKS[chainId])throw new Error("Unsupported network. Select one of the supported EVM networks.");const challenge=await api("/api/auth/challenge",{method:"POST",body:JSON.stringify({address:account,chainId})});setStatus("connectStatus","Approve the sign-in message in your wallet. It does not authorize a transaction.");const signature=await p.request({method:"personal_sign",params:[challenge.message,account]});await api("/api/auth/verify",{method:"POST",body:JSON.stringify({address:account,chainId,nonce:challenge.nonce,signature})});location.assign("/")}catch(e){setStatus("connectStatus",e.message,true)}finally{button.disabled=false}}
